// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint256).max);
        address actor = address(this); // owner: deployed in setUp with this as msg.sender
        vm.deal(actor, amount);
        uint256 balBefore = receiver.balance;
        vm.deal(address(c), amount);
        vm.prank(actor);
        c.sendTo(receiver, amount);
        assertTrue(receiver.balance == balBefore + amount, "receiver must be paid amount");
    }
}
